```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    int szczyty = 0, doliny = 0;
    vector<pair<int,int>> listaSzczytow;

    for (int i = 1; i < n - 1; i++) {
        if (T[i] > T[i - 1] && T[i] > T[i + 1]) {
            szczyty++;
            listaSzczytow.push_back({i + 1, T[i]});
        }
        if (T[i] < T[i - 1] && T[i] < T[i + 1]) {
            doliny++;
        }
    }

    cout << "a) Szczyty: " << szczyty << ", Doliny: " << doliny << endl;
    cout << endl << "b) Szczyty:" << endl;
    for (auto& p : listaSzczytow) {
        cout << "   Pozycja " << p.first << ", wartosc " << p.second << endl;
    }
    return 0;
}
```

**Wyjasnienie**: Jedna petla, dwa warunki. Szczyt: wiekszy od obu sasiadow. Dolina: mniejszy od obu sasiadow. Skrajne elementy pomijamy.

